package pickup;

import java.util.Locale;
import java.util.concurrent.atomic.AtomicInteger;
import org.hibernate.resource.jdbc.spi.StatementInspector;

/**
 * Test-only: makes Hibernate refuse one SQL statement, as a database outage
 * would, and counts the writes your code sends. A write is an insert, update
 * or delete on the provided pickup_order, order_line or product tables,
 * whichever repository or query sends it. Do not edit this file.
 */
public class SqlOutage implements StatementInspector {

    /** Refuse the next write of any kind (see refuseWrite). */
    static final String ANY_WRITE = "<any write>";

    static volatile String failingPrefix;
    static final AtomicInteger letThrough = new AtomicInteger();
    static final AtomicInteger writes = new AtomicInteger();
    static final AtomicInteger refused = new AtomicInteger();

    /** Refuse statements that start with prefix, after letting the first afterThisMany of them run. */
    static void refuse(String prefix, int afterThisMany) {
        letThrough.set(afterThisMany);
        failingPrefix = prefix;
    }

    /** Refuse a write of any kind, after letting the first afterThisMany writes run. */
    static void refuseWrite(int afterThisMany) {
        refuse(ANY_WRITE, afterThisMany);
    }

    static void end() {
        failingPrefix = null;
        letThrough.set(0);
    }

    /** Start counting writes and refused statements from zero. */
    static void startCounting() {
        writes.set(0);
        refused.set(0);
    }

    static int writes() { return writes.get(); }

    static int refused() { return refused.get(); }

    static boolean isWrite(String sql) {
        boolean dml = sql.startsWith("insert") || sql.startsWith("update") || sql.startsWith("delete")
                || sql.startsWith("merge");
        return dml && (sql.contains("pickup_order") || sql.contains("order_line") || sql.contains("product"));
    }

    @Override
    public String inspect(String sql) {
        String lower = sql.strip().toLowerCase(Locale.ROOT);
        boolean write = isWrite(lower);
        if (write) {
            writes.incrementAndGet();
        }
        String prefix = failingPrefix;
        boolean matches = prefix != null && (ANY_WRITE.equals(prefix) ? write : lower.startsWith(prefix));
        if (matches && letThrough.getAndDecrement() <= 0) {
            refused.incrementAndGet();
            throw new IllegalStateException("injected by the test: the database refused " + lower);
        }
        return sql;
    }
}
